def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (after +)
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split off pre-release (after -)
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_ids = prerelease.split('.')
            parsed_ids = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    parsed_ids.append((0, int(identifier)))  # 0 for numeric, sorts first
                else:
                    parsed_ids.append((1, identifier))  # 1 for alphanumeric, sorts after
            prerelease_tuple = tuple(parsed_ids)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(v):
        major, minor, patch, prerelease_tuple = parse_version(v)
        # Versions with prerelease sort before versions without
        # We use (major, minor, patch, 0, prerelease_tuple) for prerelease
        # and (major, minor, patch, 1) for release
        if prerelease_tuple is not None:
            return (major, minor, patch, 0, prerelease_tuple)
        else:
            return (major, minor, patch, 1)

    return sorted(versions, key=sort_key)

